import { Accordion, Text } from "@chakra-ui/react";
import type { ConversationEvent } from "../../types";
import { bargeInPlayback, formatDuration } from "../../utils/barge-in";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

interface BargeInEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}

export const BargeInEventInfo = ({ event, onClose }: BargeInEventInfoProps) => {
  const {
    confirmedThroughMs,
    interruptedWord,
    interruptedWordIndex,
    responseWordCount,
    totalAudioDurationMs,
    markerCount,
  } = bargeInPlayback(event);
  const verdict = event.metadata.barge_in_verdict;

  return (
    <DetailView title="User interrupted playback" onClose={onClose}>
      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Playback" value="playback">
          {interruptedWord !== undefined &&
            interruptedWordIndex !== undefined &&
            responseWordCount !== undefined && (
              <>
                <InfoField label="Interrupted at word">
                  <Text textStyle="sm">{interruptedWord}</Text>
                </InfoField>
                <InfoField label="Word position">
                  <Text textStyle="sm">
                    {interruptedWordIndex + 1} of {responseWordCount}
                  </Text>
                </InfoField>
              </>
            )}
          <InfoField label="Confirmed playback position">
            <Text textStyle="sm">
              {confirmedThroughMs === undefined
                ? "Unavailable"
                : formatDuration(confirmedThroughMs)}
            </Text>
          </InfoField>
          <InfoField label="Acknowledged intermediate markers">
            <Text textStyle="sm">{markerCount}</Text>
          </InfoField>
          <InfoField label="Full response duration">
            <Text textStyle="sm">
              {totalAudioDurationMs === undefined
                ? "Unknown — generation was interrupted"
                : formatDuration(totalAudioDurationMs)}
            </Text>
          </InfoField>
        </EventAccordionItem>
        <EventAccordionItem title="Barge-in decision" value="decision">
          <InfoField label="Reason">
            <Text textStyle="sm">{verdict?.reason ?? "Unavailable"}</Text>
          </InfoField>
          {verdict?.metadata?.word_count !== undefined && (
            <InfoField label="Recognized words">
              <Text textStyle="sm">{verdict.metadata.word_count}</Text>
            </InfoField>
          )}
        </EventAccordionItem>
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
